  for k in d:
    if k!='items': print('##',k,':',json.dumps(d[k])[:2000])
  items=d.get('items',[])
else: items=d
print('n items',len(items))
for it in items:
  print('---',it.get('id'),it.get('kind'),it.get('status'),'to=',it.get('to'),'from=',it.get('from_task') or it.get('from'),'read=',it.get('read'))
  print('   ',(it.get('title') or '')[:150])
" 2>&1 | head -120

